#[cfg(test)]
mod cancel_req_tests {
    use super::*;
    use bytes::BytesMut;

    #[test]
    fn test_cancel_req_codec() {
        let mut original = CancelReq {
            req_id: 123456789,
            channel_id: 1234,
            adapter: 42,
            account: "a".repeat(16),
            cl_ord_id: "a".repeat(16),
            orig_cl_ord_id: "a".repeat(16),
            security_id: "a".repeat(12),
            side: 42,
            ts_recv_ns: 123456789,
            raw_ref: 123456789,
        };

        let mut buf = BytesMut::new();
        original.encode(&mut buf);
        let bytes = buf.freeze();
        assert!(CancelReqRef::from_slice(&bytes).is_some());
        let mut reuse_bytes = bytes.clone();
        let mut reused = original.clone();
        CancelReq::decode_into(&mut reuse_bytes, &mut reused).unwrap();
        let mut bytes = bytes;

        let decoded = CancelReq::decode(&mut bytes).unwrap();
        assert_eq!(original, decoded);
        assert_eq!(original, reused);
    }
}

